8	export async function metrics_daily_has_derived_columns(ctx: AssertionContext): Promise<AssertionResult> {
9	  const rows = await queryRows<{ name: string }>(
10	    ctx,
11	    "SELECT name FROM system.columns WHERE database = 'analytics' AND table = 'metrics_daily'",
12	  );
13	  const names = rows.map((r) => r.name.toLowerCase());
14	  const hasConversion = names.some((n) => n.includes("conversion"));
15	  const hasAov = names.some((n) => n.includes("avg") || n.includes("aov") || n.includes("order_value"));
16	  const hasDau = names.some((n) => n.includes("dau") || n.includes("active") || n.includes("users"));
17	  const passed = hasConversion && (hasAov || names.some((n) => n.includes("amount"))) && hasDau;
18	  return {
19	    passed,
20	    message: passed ? "Metrics daily has derived columns." : `Missing columns. Got: ${JSON.stringify(names)}.`,
21	    details: { names, hasConversion, hasAov, hasDau },
22	  };
23	}
