10	export async function conversion_rate_in_valid_range(ctx: AssertionContext): Promise<AssertionResult> {
11	  try {
12	    const colRows = await queryRows<{ name: string }>(
13	      ctx,
14	      "SELECT name FROM system.columns WHERE database = 'analytics' AND table = 'metrics_daily'",
15	    );
16	    const convCol = colRows.find((r) => r.name.toLowerCase().includes("conversion"))?.name ?? "conversion_rate";
17	    const rows = await queryRows<Record<string, number>>(
18	      ctx,
19	      `SELECT ${convCol} AS v FROM analytics.metrics_daily WHERE ${convCol} IS NOT NULL LIMIT 1`,
20	    );
21	    if (rows.length === 0) {
22	      return { passed: false, message: "No conversion rate values.", details: {} };
23	    }
24	    const rate = Number(Object.values(rows[0] ?? {})[0] ?? -1);
25	    const passed = rate >= 0 && rate <= 1;
26	    return {
27	      passed,
28	      message: passed ? "Conversion rate in valid range." : `Conversion rate ${rate} out of [0,1].`,
29	      details: { rate },
30	    };
31	  } catch (e) {
32	    return {
33	      passed: false,
34	      message: "Could not check conversion rate.",
35	      details: { error: e instanceof Error ? e.message : String(e) },
36	    };
37	  }
38	}
